source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    row_lines = [r for r, row in enumerate(grid) if all(v == 3 for v in row)]
    col_lines = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    rb = [-1] + row_lines + [h]
    cb = [-1] + col_lines + [w]
    row_bands = [(rb[i] + 1, rb[i + 1]) for i in range(len(rb) - 1)]
    col_bands = [(cb[i] + 1, cb[i + 1]) for i in range(len(cb) - 1)]
    if len(row_bands) > 1 and len(col_bands) > 1:
        rh = row_bands[-1][1] - row_bands[-1][0]
        cw = col_bands[-1][1] - col_bands[-1][0]
        if all(b - a == rh for a, b in row_bands) and all(b - a == cw for a, b in col_bands):
            sr, sc = row_bands[-1][0], col_bands[-1][0]
            for ra, rbnd in row_bands:
                for ca, cbnd in col_bands:
                    for dr in range(rh):
                        for dc in range(cw):
                            value = grid[sr + dr][sc + dc]
                            if value != 3 and value != 5: # color 5 is background in demo
                                out[ra + dr][ca + dc] = value
    elif len(row_bands) > 1:
        sr, er = row_bands[-1]
        height = er - sr
        if all(b - a == height for a, b in row_bands):
            for a, b in row_bands[:-1]:
                for dr in range(height):
                    for c in range(w):
                        if grid[sr + dr][c] != 2:
                            out[a + dr][c] = grid[sr + dr][c]
    return out
'''
